        Self { remaining: limit }
    }

    pub fn spend(&mut self, cents: u64) -> bool {
        match self.remaining.checked_sub(cents) {
            Some(rest) => {
                self.remaining = rest;
                true
            }
            None => false,
        }
    }

    pub fn remaining(&self) -> u64 {
        self.remaining
    }
}

pub struct Line<'a> {
    pub sku: &'a str,
    pub quantity: u32,
    pub unit_cents: u64,
}

pub struct Totals {
    pub subtotal_cents: u64,
    pub discount_cents: u64,
    pub units: u32,
}

pub fn summarize(lines: &[Line<'_>], bulk_threshold: u32, bulk_percent: u64) -> Totals {
    let mut subtotal_cents = 0;
    let mut discount_cents = 0;
    let mut units = 0;
    for line in lines {
        add_line(line, &mut subtotal_cents, &mut units);
        apply_bulk(line, bulk_threshold, bulk_percent, &mut discount_cents);
    }
    build_totals(subtotal_cents, discount_cents, units)
}

fn add_line(line: &Line<'_>, subtotal_cents: &mut u64, units: &mut u32) {
    *subtotal_cents += line_cents(line);
    *units += line.quantity;
}

fn apply_bulk(line: &Line<'_>, bulk_threshold: u32, bulk_percent: u64, discount_cents: &mut u64) {
    if line.quantity >= bulk_threshold {
        *discount_cents += line_cents(line) * bulk_percent / 100;
    }
}

fn line_cents(line: &Line<'_>) -> u64 {
    u64::from(line.quantity) * line.unit_cents
}

fn build_totals(subtotal_cents: u64, discount_cents: u64, units: u32) -> Totals {
    Totals { subtotal_cents, discount_cents, units }
}

pub struct Line<'a> {
