#[derive(Debug)]
pub enum LineError {
    ZeroQuantity { sku: String },
    TooLarge { sku: String },
}

pub fn summarize(lines: &[Line<'_>]) -> Result<Totals, LineError> {
    let mut totals = Totals::default();
    for line in lines {
        totals.subtotal_cents += checked_line_cents(line)?;
        totals.units += line.quantity;
    }
    Ok(totals)
}

fn checked_line_cents(line: &Line<'_>) -> Result<u64, LineError> {
    if line.quantity == 0 {
        return Err(LineError::ZeroQuantity { sku: line.sku.to_owned() });
    }
    u64::from(line.quantity)
        .checked_mul(line.unit_cents)
        .ok_or_else(|| LineError::TooLarge { sku: line.sku.to_owned() })
}

