#[derive(Debug)]
pub struct DecodeError {
    pub line: usize,
}

pub trait Codec {
    fn content_type(&self) -> &'static str;
    fn encode(&self, rows: &[Row]) -> Vec<u8>;
    fn decode(&self, bytes: &[u8]) -> Result<Vec<Row>, DecodeError>;
}

pub struct Delimited {
    pub delimiter: char,
}

impl Codec for Delimited {
    fn content_type(&self) -> &'static str {
        if self.delimiter == '\t' {
            "text/tab-separated-values"
        } else {
            "text/csv"
        }
    }

    fn encode(&self, rows: &[Row]) -> Vec<u8> {
        let mut out = String::new();
        for row in rows {
            out.push_str(&row.name);
            out.push(self.delimiter);
            out.push_str(&row.count.to_string());
            out.push('\n');
        }
        out.into_bytes()
    }

    fn decode(&self, bytes: &[u8]) -> Result<Vec<Row>, DecodeError> {
        let text = std::str::from_utf8(bytes).map_err(|_| DecodeError { line: 0 })?;
        text.lines()
            .enumerate()
            .map(|(index, line)| {
                let (name, count) = line
                    .split_once(self.delimiter)
                    .ok_or(DecodeError { line: index + 1 })?;
                let count = count.parse().map_err(|_| DecodeError { line: index + 1 })?;
                Ok(Row { name: name.to_owned(), count })
            })
            .collect()
    }
}

pub fn export(codec: &dyn Codec, rows: &[Row]) -> (&'static str, Vec<u8>) {
    (codec.content_type(), codec.encode(rows))
}

pub fn append(codec: &dyn Codec, stored: &[u8], rows: &[Row]) -> Result<Vec<u8>, DecodeError> {
    let mut all = codec.decode(stored)?;
    all.extend_from_slice(rows);
    Ok(codec.encode(&all))
}

use std::sync::{Arc, Mutex};

#[derive(Clone)]
pub struct Row {
    pub key: String,
    pub value: i64,
}

pub struct Batcher {
    pending: Arc<Mutex<Vec<Row>>>,
    limit: usize,
}

impl Batcher {
    pub fn new(limit: usize) -> Self {
        Self { pending: Arc::new(Mutex::new(Vec::new())), limit }
    }

    pub fn push(&mut self, row: Row) -> Option<Vec<Row>> {
        let mut pending = self.pending.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        pending.push(row);
        if pending.len() < self.limit {
            return None;
        }
        let batch = pending.clone();
        pending.clear();
        Some(batch)
    }

    pub fn flush(&mut self) -> Vec<Row> {
        let mut pending = self.pending.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        let batch = pending.clone();
        pending.clear();
        batch
    }
}

use std::sync::{Arc, Mutex, MutexGuard};

#[derive(Clone)]
pub struct Row {
    pub key: String,
    pub value: i64,
}

#[derive(Clone, Default)]
pub struct Outbox {
    pending: Arc<Mutex<Vec<Row>>>,
}

impl Outbox {
    pub fn push(&self, row: Row) {
        self.rows().push(row);
    }

    pub fn snapshot(&self) -> Vec<Row> {
        self.rows().clone()
    }

    pub fn acknowledge(&self, sent: usize) {
        self.rows().drain(..sent);
    }

    fn rows(&self) -> MutexGuard<'_, Vec<Row>> {
        self.pending.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
    }
}

use std::time::Duration;

pub struct ProbeConfig {
    pub timeout_ms: u64,
    pub interval_secs: u64,
    regions: Vec<String>,
}

impl ProbeConfig {
    pub fn new(timeout_ms: u64, interval_secs: u64) -> Self {
        Self { timeout_ms, interval_secs, regions: Vec::new() }
    }

    pub fn add_region(&mut self, region: String) {
        if !self.regions.contains(&region) {
            self.regions.push(region);
            self.regions.sort();
        }
    }

    pub fn remove_region(&mut self, region: &str) {
        self.regions.retain(|existing| existing != region);
    }

    pub fn regions(&self) -> &[String] {
        &self.regions
    }
}

pub fn deadline_budget(config: &ProbeConfig, attempts: u32) -> Duration {
    Duration::from_millis(config.timeout_ms) * attempts
        + Duration::from_secs(config.interval_secs) * attempts.saturating_sub(1)
}

pub fn next_probe_in(config: &ProbeConfig, elapsed: Duration) -> Duration {
    Duration::from_secs(config.interval_secs).saturating_sub(elapsed)
}

pub fn is_slow(config: &ProbeConfig, took: Duration) -> bool {
    took > Duration::from_millis(config.timeout_ms)
}

