    pub bytes: u64,
}

#[derive(Debug)]
pub enum StatsError {
    Unavailable,
}

pub fn collect_uploads(events: &[Event], out: &mut Vec<u64>) {
    for event in events {
        if event.kind == Kind::Upload {
            out.push(event.bytes);
        }
    }
}

pub fn largest(sizes: &[u64]) -> Result<u64, StatsError> {
    Ok(sizes.iter().copied().max().unwrap_or(0))
}

pub fn largest_upload(events: &[Event]) -> Result<u64, StatsError> {
    let mut sizes = Vec::new();
    collect_uploads(events, &mut sizes);
    largest(&sizes)
}

use std::collections::VecDeque;

pub struct Event {
    pub bytes: u64,
}

#[derive(Debug)]
pub enum StatsError {
    Overflow,
}

pub fn drain_ready(queue: &mut VecDeque<Event>, limit: usize, batch: &mut Vec<Event>) {
    batch.clear();
    let ready = limit.min(queue.len());
    batch.extend(queue.drain(..ready));
}

pub trait Aggregate {
    fn total(&self, batch: &[Event]) -> Result<u64, StatsError>;
}

pub struct Wrapping;

impl Aggregate for Wrapping {
    fn total(&self, batch: &[Event]) -> Result<u64, StatsError> {
        Ok(batch.iter().fold(0u64, |sum, event| sum.wrapping_add(event.bytes)))
    }
}

pub struct Checked;

impl Aggregate for Checked {
    fn total(&self, batch: &[Event]) -> Result<u64, StatsError> {
        batch
            .iter()
            .try_fold(0u64, |sum, event| sum.checked_add(event.bytes))
            .ok_or(StatsError::Overflow)
    }
}

