pub struct Row {
    pub label: String,
    pub value: u64,
}

pub struct Report {
    pub title: String,
    pub rows: Vec<Row>,
}

pub enum Format {
    Text,
}

pub struct RenderOptions {
    pub format: Format,
    pub include_header: bool,
    pub width: usize,
}

pub fn render(report: &Report, options: &RenderOptions) -> String {
    let mut out = String::new();
    if options.include_header {
        out.push_str(&header(report, options.width));
    }
    match options.format {
        Format::Text => out.push_str(&body(report, options.width)),
    }
    out
}

pub fn header(report: &Report, width: usize) -> String {
    format!("{}\n{}\n", pad(&report.title, width), "-".repeat(width))
}

pub fn body(report: &Report, width: usize) -> String {
    report
        .rows
        .iter()
        .map(|row| format!("{}{:>8}\n", pad(&row.label, width - 8), row.value))
        .collect()
}

pub fn pad(text: &str, width: usize) -> String {
    format!("{text:<width$}")
}

pub struct Row {
    pub label: String,
    pub value: u64,
}

pub struct Report {
    pub title: String,
    pub rows: Vec<Row>,
}

pub enum Format {
    Text,
    Tsv,
}

pub struct RenderOptions {
    pub format: Format,
    pub include_header: bool,
    pub width: usize,
}

pub fn render(report: &Report, options: &RenderOptions) -> String {
    match options.format {
        Format::Text => text(report, options),
        Format::Tsv => tsv(report),
    }
}

fn text(report: &Report, options: &RenderOptions) -> String {
    let mut out = String::new();
    if options.include_header {
        out.push_str(&format!("{}\n{}\n", pad(&report.title, options.width), "-".repeat(options.width)));
    }
    for row in &report.rows {
        out.push_str(&format!("{}{:>8}\n", pad(&row.label, options.width - 8), row.value));
    }
    out
}

fn tsv(report: &Report) -> String {
    report.rows.iter().map(|row| format!("{}\t{}\n", row.label, row.value)).collect()
}

fn pad(text: &str, width: usize) -> String {
    format!("{text:<width$}")
}
